  final Object? content;
  const _CsilEpoch(this.content);

  @override
  bool operator ==(Object other) =>
      other is _CsilEpoch && CsilCbor._valueEquals(other.content, content);

  @override
  int get hashCode => content is num ? content.hashCode : 0;
}

